import json, subprocess, sys

PATH = '/workspace/submission/main.py'

def run(reqs, path=PATH, timeout=300):
    data = ''.join((l if isinstance(l, str) else json.dumps(l)) + '\n' for l in reqs)
    p = subprocess.run([sys.executable, '-I', '-B', path], input=data.encode(),
                       capture_output=True, timeout=timeout)
    assert p.returncode == 0, (p.returncode, p.stderr[-3000:])
    out = p.stdout.decode().splitlines()
    assert len(out) == len(reqs), (len(out), len(reqs), p.stderr[-2000:])
    return [json.loads(line) for line in out]
