"""Random plan instances vs brute force optimum."""
import itertools, json, random, sys
sys.path.insert(0, '/workspace/tmp')
from harness import run

ALPHA = 'abcdefghijklmnopqrstuvwxyz'

def rand_id(rng, n):
    return ''.join(rng.choice(ALPHA) for _ in range(n))

def make_case(rng):
    nnodes = rng.randint(1, 5)
    nodes = ['n%d' % i for i in range(nnodes)]
    caps = {n: rng.randint(0, 3) for n in nodes}
    if rng.random() < 0.15:
        caps = {n: rng.choice([0, 1, 512]) for n in nodes}
    nflows = rng.randint(0, 7)
    flows = []
    for i in range(nflows):
        k = rng.randint(2, min(4, nnodes))
        path = rng.sample(nodes, k)
        H = rng.randint(8, 14)
        kinds = list('KDZQT') + [rng.choice('KDZ') for _ in range(H - 5)]
        rng.shuffle(kinds)
        # ensure 4+nd < H and at least one K
        nd = kinds.count('D')
        while 4 + nd >= H or kinds.count('K') == 0:
            kinds = list('KDZQT') + [rng.choice('KDZ') for _ in range(H - 5)]
            rng.shuffle(kinds)
            nd = kinds.count('D')
        template = bytes(rng.randrange(256) for _ in range(H))
        flows.append({'id': 'f%d' % i, 'path': path,
                      'template': template.hex(), 'kinds': ''.join(kinds)})
    offers = {}
    for f in flows:
        H = len(f['template']) // 2
        kinds = f['kinds']
        path = f['path']
        runs = []
        for _ in range(rng.randint(0, 3)):
            hb = bytearray(rng.randrange(256) for _ in range(H))
            if rng.random() < 0.7:
                for pos, c in enumerate(kinds):
                    if c == 'K':
                        hb[pos] = int(f['template'][2 * pos:2 * pos + 2], 16)
                    elif c == 'Q':
                        hb[pos] = rng.choice([0, 3, 7, 8, 9])
                    elif c == 'T':
                        hb[pos] = rng.choice([0, 1, len(path) - 1, len(path), len(path) + 1, 255])
                    elif c == 'Z':
                        hb[pos] = rng.randrange(256)
            runs.append({'header': bytes(hb).hex(), 'count': rng.randint(1, 6)})
        offers[f['id']] = runs
    pinned = []
    for f in flows:
        if rng.random() < 0.2:
            pinned.append(f['id'])
    req = {'mode': 'plan', 'capacities': caps, 'flows': flows, 'warmup': rng.randint(0, 8),
           'pinned': pinned, 'offers': offers}
    return req

def benefit_of(flow, runs, warmup):
    H = len(flow['template']) // 2
    kinds = flow['kinds']
    N = len(flow['path'])
    h = N - 1
    nd = kinds.count('D')
    per = (H - 4 - nd) * N
    qo = kinds.index('Q'); to = kinds.index('T')
    tpl = bytes.fromhex(flow['template'])
    total = 0; idx = 0
    for run in runs:
        hb = bytes.fromhex(run['header']); cnt = run['count']
        end = idx + cnt
        if end > warmup:
            start = max(idx, warmup)
            elig = end - start
            ok = all(hb[i] == tpl[i] for i, c in enumerate(kinds) if c == 'K')
            ok = ok and hb[qo] <= 7 and hb[to] > h
            if ok:
                total += per * elig
        idx = end
    return total

def brute(req):
    caps = req['capacities']; flows = req['flows']
    warmup = req['warmup']; pinned = req['pinned']; offers = req['offers']
    ben = {f['id']: benefit_of(f, offers[f['id']], warmup) for f in flows}
    for p in pinned:
        assert p in ben
    pinset = set(pinned)
    usage = {}
    for f in flows:
        if f['id'] in pinset:
            for n in f['path']:
                usage[n] = usage.get(n, 0) + 1
    for n, u in usage.items():
        if u > caps[n]:
            return {'infeasible': True}
    ids = sorted(ben)
    best = None
    pinben = sum(ben[p] for p in pinned)
    for r in range(len(ids) + 1):
        for comb in itertools.combinations(ids, r):
            sel = set(comb) | pinset
            s = sorted(sel)
            use = {}
            for fid in s:
                path = next(f['path'] for f in flows if f['id'] == fid)
                for n in path:
                    use[n] = use.get(n, 0) + 1
            if any(use.get(n, 0) > caps[n] for n in caps):
                continue
            val = (sum(ben[f] for f in s), -len(s))
            if best is None or val > best[0]:
                best = (val, s)
    if best is None:
        # only pinned, feasible
        return {'selected': sorted(pinset), 'saved': pinben}
    return {'selected': best[1], 'saved': best[0][0]}

def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 300
    reqs = [make_case(rng) for _ in range(n)]
    got = run(reqs)
    bad = 0
    for req, g in zip(reqs, got):
        exp = brute(req)
        if g != exp:
            bad += 1
            print('MISMATCH')
            print(json.dumps(req))
            print('got', json.dumps(g, sort_keys=True))
            print('exp', json.dumps(exp, sort_keys=True))
            if bad > 3:
                break
    print('cases', n, 'mismatches', bad)

main()
